// (Set)-[:HAS_INVENTORY]->(Inv)-[:CONTAINS_SET]->(Set)-[:HAS_INVENTORY]->(Inv)-[:HAS_PART]->(Part)
// (Set)-[:HAS_INVENTORY]->(Inv)-[:CONTAINS_MINIFIG]->(Minifig)-[:HAS_INVENTORY]->(Inv)-[:HAS_PART]->(Part)

