MATCH (s:Set)
MATCH p_fig = (s)-[:CONTAINS*1..20]->(:Minifig {fig_num: 'fig-014663'})
WHERE all(i IN range(0, length(rels(p_fig)) - 1) WHERE
  rels(p_fig)[i].qty > 0
  AND NOT EXISTS {
    MATCH (parent)-[newer:CONTAINS]->()
    WHERE parent = nodes(p_fig)[i]
      AND newer.version > rels(p_fig)[i].version
  }
)
MATCH p_part = (s)-[:CONTAINS*1..20]->(:Part {part_num: '14418'})
WHERE all(i IN range(0, length(rels(p_part)) - 1) WHERE
  rels(p_part)[i].qty > 0
  AND rels(p_part)[i].is_spare = false
  AND NOT EXISTS {
    MATCH (parent)-[newer:CONTAINS]->()
    WHERE parent = nodes(p_part)[i]
      AND newer.version > rels(p_part)[i].version
  }
)
RETURN count(DISTINCT s) AS set_count;
```

