MATCH (s:Set)-[:HAS_INVENTORY]->(i0:Inventory)-[:CONTAINS_MINIFIG]->(m:Minifig {fig_num: 'fig-001686'})
WHERE NOT EXISTS { MATCH (s)-[:HAS_INVENTORY]->(x:Inventory) WHERE x.version > i0.version }
RETURN s.set_num AS set_num
UNION
MATCH (s:Set)-[:HAS_INVENTORY]->(i0:Inventory)-[:CONTAINS_SET]->(s1:Set)-[:HAS_INVENTORY]->(i1:Inventory)-[:CONTAINS_MINIFIG]->(m:Minifig {fig_num: 'fig-001686'})
WHERE NOT EXISTS { MATCH (s)-[:HAS_INVENTORY]->(x:Inventory) WHERE x.version > i0.version }
  AND NOT EXISTS { MATCH (s1)-[:HAS_INVENTORY]->(y:Inventory) WHERE y.version > i1.version }
RETURN s.set_num AS set_num
UNION
MATCH (s:Set)-[:HAS_INVENTORY]->(i0:Inventory)-[:CONTAINS_SET]->(s1:Set)-[:HAS_INVENTORY]->(i1:Inventory)-[:CONTAINS_SET]->(s2:Set)-[:HAS_INVENTORY]->(i2:Inventory)-[:CONTAINS_MINIFIG]->(m:Minifig {fig_num: 'fig-001686'})
WHERE NOT EXISTS { MATCH (s)-[:HAS_INVENTORY]->(x:Inventory) WHERE x.version > i0.version }
  AND NOT EXISTS { MATCH (s1)-[:HAS_INVENTORY]->(y:Inventory) WHERE y.version > i1.version }
  AND NOT EXISTS { MATCH (s2)-[:HAS_INVENTORY]->(z:Inventory) WHERE z.version > i2.version }
RETURN s.set_num AS set_num
UNION
